def signature_base_string(http_method: str, base_str_uri: str,
    normalized_encoded_request_parameters: str) ->str:
    collecting = [
        utils.escape(http_method.upper()),
        utils.escape(base_str_uri),
        utils.escape(normalized_encoded_request_parameters),
    ]
    return '&'.join(collecting)

def base_string_uri(uri: str, host: str=None) ->str:
    if not isinstance(uri, str):
        raise ValueError('uri must be a string')
    if not uri or uri.strip() == '':
        raise ValueError('uri is empty')

    uri = uri.strip()

    parsed = urlparse.urlparse(uri)

    scheme = parsed.scheme
    if not scheme:
        raise ValueError('uri has no scheme')
    scheme = scheme.lower()

    netloc = parsed.netloc
    if host is not None:
        netloc = host

    if not netloc:
        raise ValueError('uri has no host')

    if '@' in netloc:
        netloc = netloc.split('@', 1)[1]

    if ':' in netloc:
        host_part, port_part = netloc.rsplit(':', 1)
        if '[' in host_part or (']' in netloc and netloc.index(']') > netloc.index(':')):
            pass
        else:
            if not host_part:
                raise ValueError('uri has no host')
            port_str = port_part.strip()
            if port_str == '':
                netloc = host_part
            else:
                try:
                    port_num = int(port_str)
                except ValueError:
                    raise ValueError('uri has invalid port: {}'.format(port_str))
                if port_num <= 0 or port_num > 65535:
                    raise ValueError('uri has invalid port number: {}'.format(port_num))
                default_ports = {'http': 80, 'https': 443}
                if scheme in default_ports and default_ports[scheme] == port_num:
                    netloc = host_part
                else:
                    netloc = '{}:{}'.format(host_part, port_num)

    if '[' in netloc:
        bracket_end = netloc.find(']')
        if bracket_end != -1:
            after_bracket = netloc[bracket_end+1:]
            if ':' in after_bracket:
                host_part = netloc[:bracket_end+1]
                port_str = after_bracket[1:].strip()
                if port_str == '':
                    netloc = host_part
                else:
                    try:
                        port_num = int(port_str)
                    except ValueError:
                        raise ValueError('uri has invalid port: {}'.format(port_str))
                    if port_num <= 0 or port_num > 65535:
                        raise ValueError('uri has invalid port number: {}'.format(port_num))
                    default_ports = {'http': 80, 'https': 443}
                    if scheme in default_ports and default_ports[scheme] == port_num:
                        netloc = host_part
                    else:
                        netloc = '{}:{}'.format(host_part, port_num)

    netloc = netloc.lower()

    path = parsed.path
    if not path:
        path = '/'

    path = urlparse.quote(urlparse.unquote(path), safe='/-._~!$&\'()*+,;=:@')

    result = '{}://{}{}'.format(scheme, netloc, path)
    return result

def normalize_parameters(params) ->str:
    key_values = []
    for k, v in params:
        encoded_k = utils.escape(k)
        encoded_v = utils.escape(v)
        key_values.append((encoded_k, encoded_v))
    key_values.sort()
    return '&'.join('{}={}'.format(k, v) for k, v in key_values)

def _get_jwt_rsa_algorithm(hash_algorithm_name: str):
    if hash_algorithm_name in _jwt_rsa:
        return _jwt_rsa[hash_algorithm_name]

    from jwt.algorithms import RSAAlgorithm
    alg = RSAAlgorithm(getattr(RSAAlgorithm, hash_algorithm_name))
    _jwt_rsa[hash_algorithm_name] = alg
    return alg

def _prepare_key_plus(alg, keystr):
    if isinstance(keystr, bytes):
        keystr = keystr.decode('utf-8')
    return alg.prepare_key(keystr)

def _sign_rsa(hash_algorithm_name: str, sig_base_str: str, rsa_private_key: str
    ):
    if rsa_private_key is None or rsa_private_key == '':
        raise ValueError('rsa_private_key is required')

    alg = _get_jwt_rsa_algorithm(hash_algorithm_name)
    key = _prepare_key_plus(alg, rsa_private_key)

    sig_base_str_bytes = sig_base_str.encode('utf-8') if isinstance(sig_base_str, str) else sig_base_str
    signature = alg.sign(sig_base_str_bytes, key)
    return binascii.b2a_base64(signature)[:-1].decode('utf-8')

def _verify_rsa(hash_algorithm_name: str, request, rsa_public_key: str):
    norm_params = normalize_parameters(request.params)
    bs_uri = base_string_uri(request.uri)
    sig_base_str = signature_base_string(request.http_method, bs_uri, norm_params)

    alg = _get_jwt_rsa_algorithm(hash_algorithm_name)

    from cryptography.hazmat.primitives.asymmetric.rsa import RSAPublicKey
    if not isinstance(rsa_public_key, RSAPublicKey):
        raise TypeError('rsa_public_key must be an RSA public key object')

    sig_base_str_bytes = sig_base_str.encode('utf-8') if isinstance(sig_base_str, str) else sig_base_str

    try:
        signature = binascii.a2b_base64(request.signature)
        result = alg.verify(sig_base_str_bytes, rsa_public_key, signature)
    except Exception:
        result = False

    if not result:
        log.debug('Verify RSA failed')
    return result

def sign_rsa_sha1_with_client(sig_base_str, client):
    return _sign_rsa('SHA-1', sig_base_str, client.rsa_key)

def verify_rsa_sha1(request, rsa_public_key: str):
    return _verify_rsa('SHA-1', request, rsa_public_key)

def sign_rsa_sha256_with_client(sig_base_str: str, client):
    return _sign_rsa('SHA-256', sig_base_str, client.rsa_key)

def verify_rsa_sha256(request, rsa_public_key: str):
    return _verify_rsa('SHA-256', request, rsa_public_key)

def sign_rsa_sha512_with_client(sig_base_str: str, client):
    return _sign_rsa('SHA-512', sig_base_str, client.rsa_key)

def verify_rsa_sha512(request, rsa_public_key: str):
    return _verify_rsa('SHA-512', request, rsa_public_key)
